import type { GoslingSpec } from '@gosling-lang/gosling-schema';

// WHO flu (USA), rebuilt with the period coordinate system from the original `who_flu_usa.csv`.
// Supplementary Fig. S7 / paper Fig. 1A drew its ring from a hand-made file in which every date was moved
// into 2010; here `period` wraps the time axis by year instead. The years are ISO week-based (`weekBased`),
// so ISO week 1 is at 12 o'clock in every year, also when it starts in late December (2014-W01 starts on
// 2013-12-30).
//
// Time coordinate systems: the ring and the season comparison share the period system
// "year, ISO weeks", so the brush on the ring drives the comparison view; the timeline below is absolute
// time and is linked to neither.

// The ISO_SDATE column holds local (CET) midnight exported as UTC, i.e. Sunday 23:00 UTC, which falls in the
// previous ISO week. So the dates are read from the year and week columns: with `includesCalendarWeek`,
// the Monday of each ISO week is stored, as Unix seconds, in the first field (`ISO_YEAR`).
const FLU = {
    url: 'https://raw.githubusercontent.com/vanessastoiber/thesis-datasets/main/5_who-flu/who_flu_usa.csv',
    type: 'csv-time',
    dateFields: ['ISO_YEAR', 'ISO_WEEK'],
    includesCalendarWeek: true
} as const;

/** Wrap the time axis by ISO week-based year; each row's year is stored in the field `year`. */
const PERIOD = { unit: 'year', weekBased: true, newField: 'year' } as const;

const YEAR_COLOR = {
    field: 'year',
    type: 'nominal',
    domain: ['2010', '2011', '2012', '2013', '2014'],
    range: ['#C635BB', '#E5C011', '#12C340', '#1279C3', '#CC2F06'],
    title: 'Year'
} as const;

const CASES = { field: 'INF_A', type: 'quantitative', domain: [0, 14000], title: 'Cases per week' } as const;

const spec = {
    title: 'When in the year does influenza A peak?',
    subtitle: 'Weekly influenza A cases, USA, 2010 to 2014; brush the ring to compare weeks. Source: WHO FluNet',
    arrangement: 'vertical',
    views: [
        {
            arrangement: 'horizontal',
            views: [
                {
                    // --- Ring: every year on one revolution, week 1 at 12 o'clock ---
                    layout: 'circular',
                    centerRadius: 0.45,
                    tracks: [
                        {
                            alignment: 'overlay',
                            data: FLU,
                            x: { field: 'ISO_YEAR', type: 'temporal', period: PERIOD, axis: 'top' },
                            y: CASES,
                            tracks: [
                                { mark: 'line', color: { ...YEAR_COLOR, legend: true }, size: { value: 2 } },
                                // a brush in the period coordinate system: it selects weeks of every year at once
                                {
                                    mark: 'brush',
                                    x: { linkingId: 'weeks' },
                                    color: { value: 'gray' },
                                    opacity: { value: 0.12 }
                                }
                            ],
                            width: 380,
                            height: 120
                        }
                    ]
                },
                {
                    // --- Season comparison: the same period system on a linear axis, driven by the brush ---
                    tracks: [
                        {
                            title: 'Selected weeks, every year',
                            data: FLU,
                            mark: 'line',
                            x: {
                                field: 'ISO_YEAR',
                                type: 'temporal',
                                period: PERIOD,
                                axis: 'bottom',
                                linkingId: 'weeks'
                            },
                            y: { ...CASES, axis: 'left' },
                            color: { ...YEAR_COLOR, legend: true },
                            size: { value: 2 },
                            width: 420,
                            height: 380
                        }
                    ]
                }
            ]
        },
        {
            // --- Timeline: absolute time, a separate coordinate system (not linked to the period views) ---
            tracks: [
                {
                    title: 'All weeks, 2010 to 2014',
                    data: FLU,
                    mark: 'bar',
                    x: { field: 'ISO_YEAR', type: 'temporal', axis: 'bottom', domain: { interval: ['2010', '2014'] } },
                    y: CASES,
                    color: { value: 'black' },
                    size: { value: 2 },
                    width: 820,
                    height: 100
                }
            ]
        }
    ]
};

export const EX_SPEC_TEMPORAL_WHO_FLU_PERIOD = spec as unknown as GoslingSpec;
import type { GoslingSpec } from '@gosling-lang/gosling-schema';

// Supplementary material, Fig. S7 (WHO Flu Data; paper Fig. 1A).
// Copied from the supplementary PDF (a fragment, wrapped in a root object). Fixed since
// (docs/grammar-audit.md §7): the circular view shows one year (2010), as in the published figure,
// instead of the root domain (2009-09 to 2012-04), and the two comparison views, which had no data,
// read the superimposed file.
//
// `who_flu_usa_superimposed` is `who_flu_usa.csv` with the year of every ISO_SDATE set to 2010
// (ISO_YEAR keeps the real year), which is what stacks the seasons on one ring. It was made by hand,
// and ISO week 1 of 2013, 2014 and 2015 starts in late December, so those points sit at the end of
// the ring instead of the start. Left as is on purpose: a period-based cyclic layout should replace
// this preprocessing (see the period example).
// Since fixed: the two linear views show the end and the start of the season instead of the same range, the
// timeline covers all years, and every view has titles, axis titles and a year legend.

const SUPERIMPOSED_DATA = {
    url: 'https://raw.githubusercontent.com/vanessastoiber/thesis-datasets/main/5_who-flu/who_flu_usa_superimposed',
    type: 'csv-time',
    dateFields: ['ISO_SDATE']
};

const YEARS = {
    field: 'ISO_YEAR',
    type: 'nominal',
    domain: ['2010', '2011', '2012', '2013', '2014'],
    range: ['#C635BB', '#E5C011', '#12C340', '#1279C3', '#CC2F06'],
    title: 'Year'
} as const;

const spec = {
    title: 'Does the flu season peak at the same time every year?',
    subtitle: 'Influenza A per week, USA, 2010 to 2014, all drawn over 2010. Source: WHO FluNet',
    xDomain: { interval: [1251763200, 1333238400] },

    arrangement: 'vertical',
    spacing: 20,

    views: [
        {
            // --- Circular overview: highlights seasonal (cyclic) patterns ---
            spacing: 0,
            layout: 'circular',
            alignment: 'stack',
            centerRadius: 0.45,
            // one ring per year: the superimposed data covers 2010 only
            xDomain: { interval: [1262304000, 1293840000] },

            data: SUPERIMPOSED_DATA,

            tracks: [
                {
                    mark: 'line',
                    size: { value: 2.5 },

                    // Color encodes year for comparison across cycles
                    color: { ...YEARS, legend: true },

                    x: { field: 'ISO_SDATE', type: 'temporal', axis: 'top' },
                    y: { field: 'INF_A', type: 'quantitative', domain: [0, 15000], title: 'Cases per week' },

                    style: { outlineWidth: 0 },
                    width: 400,
                    height: 100
                }
            ]
        },

        {
            // --- Linear comparison views: support direct year-to-year comparison ---
            spacing: 30,
            arrangement: 'horizontal',

            // the two halves of the season: its end (January to May) and its start (September to December)
            views: [
                {
                    xDomain: { interval: ['2010-01', '2010-05'] },
                    tracks: [
                        {
                            title: 'End of the season',
                            data: SUPERIMPOSED_DATA,
                            mark: 'line',
                            size: { value: 2.5 },

                            color: YEARS,

                            x: { field: 'ISO_SDATE', type: 'temporal', axis: 'bottom' },
                            y: {
                                field: 'INF_A',
                                type: 'quantitative',
                                domain: [0, 10000],
                                title: 'Cases per week'
                            },

                            width: 300,
                            height: 150
                        }
                    ]
                },
                {
                    xDomain: { interval: ['2010-09', '2010-12'] },
                    tracks: [
                        {
                            title: 'Start of the season',
                            data: SUPERIMPOSED_DATA,
                            mark: 'line',
                            size: { value: 2.5 },

                            // the legend of these colors is in the center of the ring
                            color: YEARS,

                            x: { field: 'ISO_SDATE', type: 'temporal', axis: 'bottom' },
                            y: {
                                field: 'INF_A',
                                type: 'quantitative',
                                domain: [0, 10000],
                                title: 'Cases per week'
                            },

                            width: 300,
                            height: 150
                        }
                    ]
                }
            ]
        },

        {
            // --- Timeline overview: provides global temporal context ---
            alignment: 'overlay',
            title: 'All weeks, 2010 to 2014',
            width: 600,
            height: 130,
            // the whole timeline, so that every year's band is visible
            xDomain: { interval: ['2010', '2014'] },

            data: {
                url: 'https://raw.githubusercontent.com/vanessastoiber/thesis-datasets/main/5_who-flu/who_flu_usa.csv',
                type: 'csv-time',
                dateFields: ['ISO_SDATE']
            },

            tracks: [
                {
                    // Weekly flu cases over time, colored by year as in the ring (the published figure drew
                    // colored year bands with labels above the bars instead)
                    mark: 'bar',
                    color: { ...YEARS, legend: true },
                    size: { value: 5 },

                    x: { field: 'ISO_SDATE', type: 'temporal', axis: 'bottom' },
                    y: { field: 'INF_A', type: 'quantitative', domain: [0, 14000], title: 'Cases per week' },

                    width: 400,
                    height: 130
                }
            ]
        }
    ]
};

export const EX_SPEC_TEMPORAL_SUPP_WHO_FLU = spec as unknown as GoslingSpec;
